import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CXsxtpvq.js";const n="/asset-studio/shots/en/12-gallery.webp",s="/asset-studio/shots/en/13-gallery-lightbox.webp",i="/asset-studio/shots/en/15-gallery-passed.webp",f=JSON.parse('{"title":"Gallery and review","description":"","frontmatter":{},"headers":[],"relativePath":"guide/gallery.md","filePath":"guide/gallery.md"}'),g={name:"guide/gallery.md"};function l(d,e,p,h,c,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="gallery-and-review" tabindex="-1">Gallery and review <a class="header-anchor" href="#gallery-and-review" aria-label="Permalink to &quot;Gallery and review&quot;">​</a></h1><p>The <strong>Gallery</strong> shows every image under <code>outputs/</code>. Here you review images as pass or fail; passed images are what you export and train on.</p><p><img src="'+n+'" alt="Gallery"></p><h2 id="filtering-and-sorting" tabindex="-1">Filtering and sorting <a class="header-anchor" href="#filtering-and-sorting" aria-label="Permalink to &quot;Filtering and sorting&quot;">​</a></h2><p>Filter by character, outfit, expression, rating (general / adult) and model family at the top.</p><ul><li><strong>Latest image of each</strong>: only the newest image per expression.</li><li><strong>My verdict</strong>: only unreviewed, passed or failed images.</li><li><strong>Adopted only</strong>: only the one adopted image per expression.</li></ul><p>When you come back to the gallery after generating, <strong>New images · refresh</strong> appears if images were added since your last visit.</p><h2 id="looking-at-an-image" tabindex="-1">Looking at an image <a class="header-anchor" href="#looking-at-an-image" aria-label="Permalink to &quot;Looking at an image&quot;">​</a></h2><p>Click an image to open it large with its record on the right (model, seed, prompt, settings). Use ← / → to move and <strong>View at 100%</strong> for full size.</p><p><img src="'+s+'" alt="Image and its record"></p><p>Review quickly from the keyboard: <strong>P</strong> pass, <strong>F</strong> fail, <strong>U</strong> unreviewed.</p><h2 id="review-and-adoption" tabindex="-1">Review and adoption <a class="header-anchor" href="#review-and-adoption" aria-label="Permalink to &quot;Review and adoption&quot;">​</a></h2><p>Tick <strong>Select</strong> on the cards and press <strong>Pass selected</strong> or <strong>Fail selected</strong> to judge many at once.</p><p><img src="'+i+'" alt="Passing several images"></p><p>For each character, outfit and expression, one of the passed images is <strong>★ Adopted</strong> (the one passed most recently). The adopted image represents that expression: ZIP export and the default LoRA dataset use it.</p><h2 id="regenerating" tabindex="-1">Regenerating <a class="header-anchor" href="#regenerating" aria-label="Permalink to &quot;Regenerating&quot;">​</a></h2><p><strong>Regenerate with a new seed</strong> makes a new image from the chosen image&#39;s record with only the seed changed. Changes made later in the image tools are not reproduced.</p><h2 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h2><p><strong>Export current scope as ZIP</strong> downloads the adopted image of each expression in the current filter as <code>&lt;work&gt;/&lt;character&gt;/&lt;outfit&gt;/&lt;expression&gt;.png</code>. If some expressions are missing it says so, and <strong>Export without the missing ones</strong> downloads what is there.</p><h2 id="sending-to-the-image-tools" tabindex="-1">Sending to the image tools <a class="header-anchor" href="#sending-to-the-image-tools" aria-label="Permalink to &quot;Sending to the image tools&quot;">​</a></h2><p>Send the chosen images to the <a href="./tools">image tools</a> for tagging, inpainting, background removal or censoring.</p>',21)])])}const y=a(g,[["render",l]]);export{f as __pageData,y as default};
